#!/usr/bin/env python3
"""Build the zero-network static replay from checked-in calculated evidence."""
import json,pathlib
R=pathlib.Path(__file__).resolve().parent
rows=json.loads((R/'evidence/replay.json').read_text())
cases=json.loads((R/'fixtures/cases.json').read_text())
data=json.dumps([dict(report=r,case=c) for r,c in zip(rows,cases)],ensure_ascii=False).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'; img-src data:; base-uri 'none'; form-action 'none'"><title>PRIME · inspect the boundary</title>
<style>
:root{font-family:ui-sans-serif,system-ui,sans-serif;color:#eaf0ef;background:#101d22;line-height:1.5;color-scheme:dark}*{box-sizing:border-box}body{margin:0}header,main,footer{max-width:1180px;margin:auto;padding:28px}header{padding-top:48px}.eyebrow{font-size:12px;letter-spacing:.17em;text-transform:uppercase;color:#91c8bd}h1{font-size:clamp(34px,5vw,60px);line-height:1.05;letter-spacing:-.045em;margin:12px 0 18px;max-width:860px;font-weight:600}p{color:#b8c7c9;max-width:800px}.numbers{display:flex;gap:28px;margin:28px 0}.numbers div{border-left:2px solid #578c80;padding:4px 18px}.numbers strong{display:block;font-size:30px;line-height:1.1}.numbers span{font-size:12px;color:#a9c0be}.boundary{background:#24383b;border:1px solid #49645f;border-radius:14px;padding:20px;margin-bottom:26px}.boundary p{margin:5px 0}a{color:#9bdaca}select,button{background:#263d43;color:#eff6f4;border:1px solid #51757a;border-radius:7px;padding:12px;font:inherit}select{width:100%;margin:8px 0 22px}button{cursor:pointer;margin:0 8px 10px 0;font-size:13px}button[aria-pressed=true]{background:#9bdaca;color:#10282d}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:#172b31;border:1px solid #365057;border-radius:14px;padding:22px;min-width:0}h2{font-size:22px;margin:0 0 8px}h3{font-size:14px;text-transform:uppercase;letter-spacing:.07em;color:#91c8bd;margin:18px 0 8px}pre{font-family:ui-monospace,SFMono-Regular,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#0d2026;border-radius:7px;padding:15px;font-size:12px;max-height:450px;overflow:auto}.source{font-size:15px;color:#e1e8e5}.pill{display:inline-block;background:#38554b;border:1px solid #64917b;color:#cdf0d3;border-radius:30px;padding:4px 11px;font-size:12px}.denied{background:#463d31;border-color:#8e7752;color:#f5d7a9}.trace{padding:13px;border-top:1px solid #375159;margin-top:10px}.note{font-size:14px;color:#d0d9d2}.limit{background:#3a342c;border-left:3px solid #b4945e;padding:18px;border-radius:0 10px 10px 0;margin-top:24px}footer{font-size:12px;color:#8ca4a5;border-top:1px solid #365057;margin-top:20px}.chain{display:flex;gap:8px;align-items:center;color:#9db6b6;font-size:12px;flex-wrap:wrap}.chain span{border:1px solid #3d5d61;border-radius:7px;padding:8px}details summary{cursor:pointer;color:#aad1c7;margin:18px 0}@media(max-width:760px){.grid{grid-template-columns:1fr}header,main,footer{padding:20px}.numbers{gap:4px}.numbers div{padding:3px 12px}.numbers strong{font-size:24px}}
</style><header><div class="eyebrow">AEE × LOGODECRYPT · synthetic defensive evaluation</div><h1>Inspect the evidence.<br>Separate it from authority.</h1><p>PRIME makes selected text patterns and source changes inspectable. A different, explicit mock gate decides which proposed actions are permitted. This replay lets you see the difference.</p><div class="numbers"><div><strong>18</strong><span>synthetic scenarios</span></div><div><strong>19</strong><span>specified decisions</span></div><div><strong>26</strong><span>regression tests</span></div></div><div class="chain"><span>Untrusted text</span>→<span>PRIME evidence</span>+<span>Separate authority check</span>→<span>Inert trace + receipt</span></div></header><main><div class="boundary"><h2>The ablation is the boundary.</h2><p>Removing PRIME leaves all gate decisions unchanged. The mock authorization rules cause the containment shown here. PRIME’s distinct, bounded contribution is its review evidence—not automatic attack neutralization.</p></div><label for="case">Choose a recorded specimen</label><select id="case"></select><div id="note" class="note"></div><div style="margin:18px 0"><button id="sourceBtn" aria-pressed="true">Source and outcome</button><button id="metricBtn" aria-pressed="false">Measured PRIME evidence</button></div><section id="sourceView" class="grid"><article class="panel"><h2>Read what entered</h2><h3>Untrusted specimen</h3><pre class="source" id="text"></pre><h3>Independent comparison context</h3><pre class="source" id="context"></pre><p class="note">Actions are specified by the test author. No live model or agent interprets these instructions.</p></article><article class="panel"><h2>Trace the proposed action</h2><div id="events"></div><p class="note">Every allowed result is an in-memory demo event. Nothing is sent, deleted, changed or fetched from another system.</p></article></section><section id="metricView" hidden class="grid"><article class="panel"><h2>Source-paired observables</h2><h3>Number and selected polarity changes</h3><pre id="fidelity"></pre><h3>Script and format controls</h3><pre id="scripts"></pre></article><article class="panel"><h2>Measurements, not verdicts</h2><pre id="battery"></pre><p class="note">PIC and T_d are historical formula labels—not calibrated threat probabilities, truth determinations or malware-defense guarantees.</p><h3>Source SHA-256</h3><pre id="hash"></pre><p class="note">Unsigned hashes are not identity, independent timestamps or signatures. A writer can replace both content and digest.</p></article></section><div class="limit"><h2>Keep the misses in view.</h2><p>The status-drift and number/actor-rebinding specimens produce no selected cue difference despite changed meaning. A benign quoted warning triggers the toy keyword baseline. These cases are included so the demonstration cannot quietly become a universal detection claim.</p></div><details><summary>Inspect the complete recorded report</summary><pre id="full"></pre></details><p><a href="https://github.com/socio-sapien/prime-security-demonstrator">Code, reproducible tests and evaluation protocol</a></p></main><footer>Local, static replay · no uploads, analytics, model calls or external scripts. Rebuild with Python to recompute PRIME. Synthetic conformance is not independent product validation or a commercial commitment.</footer>
<script id="data" type="application/json">DATA_MARKER</script><script>
'use strict';const rows=JSON.parse(document.getElementById('data').textContent);const $=id=>document.getElementById(id);const select=$('case');rows.forEach((x,i)=>{const o=document.createElement('option');o.value=i;o.textContent=x.case.label+' · '+x.case.id;select.append(o)});function show(){const x=rows[Number(select.value)],r=x.report;$('note').textContent=x.case.note;$('text').textContent=r.source_text;$('context').textContent=r.context_text;$('fidelity').textContent=JSON.stringify(r.prime.context_fidelity,null,2);$('scripts').textContent=JSON.stringify(r.prime.scripts,null,2);$('battery').textContent=JSON.stringify(r.prime.battery,null,2);$('hash').textContent=r.source_sha256;$('full').textContent=JSON.stringify(r,null,2);$('events').replaceChildren();r.events.forEach(e=>{const box=document.createElement('div');box.className='trace';const tag=document.createElement('span');tag.className='pill'+(e.allowed?'':' denied');tag.textContent=e.allowed?'ALLOWED · INERT EVENT':'DENIED · NOT DISPATCHED';box.append(tag);const pre=document.createElement('pre');pre.textContent=JSON.stringify(e.proposed_action,null,2);box.append(pre);const p=document.createElement('p');p.textContent=e.reason;box.append(p);$('events').append(box)})}select.addEventListener('change',show);function view(metric){$('sourceView').hidden=metric;$('metricView').hidden=!metric;$('sourceBtn').setAttribute('aria-pressed',String(!metric));$('metricBtn').setAttribute('aria-pressed',String(metric))}$('sourceBtn').onclick=()=>view(false);$('metricBtn').onclick=()=>view(true);show();
</script></html>'''
# Explicit [hidden] beats display:grid in author styles.
html=html.replace(':root{', '[hidden]{display:none!important}:root{')
(R/'site/index.html').write_text(html.replace('DATA_MARKER',data))
